`timescale 1ns/1ps
`define MANUAL_LOAD

module new_tb;

// =========================================================
// CLOCK + RESET
// =========================================================
reg clk_tb;
reg rst_n_tb;

initial begin
    clk_tb = 0;
    forever #5 clk_tb = ~clk_tb;
end

initial begin
    rst_n_tb = 0;
    repeat (50) @(posedge clk_tb);
    rst_n_tb = 1;
    $display("[%0t] Reset released", $time);
end

// =========================================================
// APB SIGNALS
// =========================================================
reg         psel_tb;
reg         penable_tb;
reg         pwrite_tb;
reg  [11:2] paddr_tb;
reg  [31:0] pwdata_tb;
reg  [3:0]  pstrb_tb;

wire [31:0] prdata_tb;
wire        pready_tb;
wire        pslverr_tb;

// =========================================================
// DUT INSTANTIATION
// =========================================================
accel_subsystem_top DUT (
    .i_clk      (clk_tb),
    .i_rst_n    (rst_n_tb),
    .i_PSEL     (psel_tb),
    .i_PENABLE  (penable_tb),
    .i_PWRITE   (pwrite_tb),
    .i_PADDR    (paddr_tb),
    .i_PWDATA   (pwdata_tb),
    .i_PSTRB    (pstrb_tb),
    .o_PRDATA   (prdata_tb),
    .o_PREADY   (pready_tb),
    .o_PSLVERR  (pslverr_tb)
);

initial begin
    psel_tb    = 0;
    penable_tb = 0;
    pwrite_tb  = 0;
    paddr_tb   = 0;
    pwdata_tb  = 0;
    pstrb_tb   = 4'hF;
end

// =========================================================
// ADDRESS MAP (APB register word indices)
// =========================================================
// Weight data registers : indices 0..7
// Weight address reg    : index 8
//   bit[7:0] = SRAM row address
//   bit[8]   = 1 ? weight SRAM selected
//   bit[9]   = 1 ? clauses SRAM selected
// Weight CMD reg        : index 9
//   bit[0]=weight_write  bit[1]=weight_read
//   bit[2]=clause_write  bit[3]=clause_read
// Image data regs       : indices 10..41
// Image CMD reg         : index 42
// Result reg (RO)       : index 43
// Model params reg      : index 44
// Load done reg         : index 45  (stop signal to class_top)

localparam integer IMG_BASE_ADDR     = 10;
localparam integer IMG_CMD_ADDR      = 42;
localparam integer RESULT_ADDR       = 43;
localparam integer MODEL_PARAMS_ADDR = 44;
localparam integer LOAD_DONE_ADDR    = 45;

// Address select bits for weights_clauses_glue
// bit[8]=1 selects weight SRAM, bit[9]=1 selects clauses SRAM
localparam integer WEIGHT_SEL_BIT = 32'h100;   // bit[8]
localparam integer CLAUSE_SEL_BIT = 32'h200;   // bit[9]

localparam [18:0] MODEL_PARAMS = 19'b1010_010001100_001_111;

// =========================================================
// APB WRITE TASK
// =========================================================
task apb_write_idx(input [9:0] word_index, input [31:0] data);
begin
    @(posedge clk_tb);
    psel_tb    <= 1;
    pwrite_tb  <= 1;
    penable_tb <= 0;
    paddr_tb   <= word_index;
    pwdata_tb  <= data;
    pstrb_tb   <= 4'hF;

    @(posedge clk_tb);
    penable_tb <= 1;
    while (!pready_tb) @(posedge clk_tb);

    @(posedge clk_tb);
    psel_tb    <= 0;
    penable_tb <= 0;
    pwrite_tb  <= 0;
end
endtask

// =========================================================
// APB READ TASK
// =========================================================
task apb_read_idx(input [9:0] word_index, output [31:0] data);
begin
    @(posedge clk_tb);
    psel_tb    <= 1;
    pwrite_tb  <= 0;
    penable_tb <= 0;
    paddr_tb   <= word_index;

    @(posedge clk_tb);
    penable_tb <= 1;
    while (!pready_tb) @(posedge clk_tb);
    data = prdata_tb;

    @(posedge clk_tb);
    psel_tb    <= 0;
    penable_tb <= 0;
end
endtask

// =========================================================
// MEMORY STORAGE
// =========================================================
reg [127:0] image_mem  [0:79];
reg [255:0] weight_mem [0:49];
reg [255:0] clause_mem [0:139];

// =========================================================
// FILE READERS
// =========================================================
task read_image_file;
begin
     $display("\n=== READING IMAGE FILE ===");
    $readmemb("image.txt", image_mem, 0, 79);  // <-- explicit range, stops at line 79
    $display("image_mem[0]  = %h", image_mem[0]);  // line 0 of image 0
    $display("image_mem[1]  = %h", image_mem[1]);  // line 0 of image 0
    $display("image_mem[7]  = %h", image_mem[7]);  // line 7 of image 0
    $display("image_mem[8]  = %h", image_mem[8]);  // line 0 of image 1
    $display("image_mem[15] = %h", image_mem[15]); // line 7 of image 1
end
endtask

