// =========================================================
// WEIGHT SRAM ACCESS
// ---------------------------------------------------------
// weights_clauses_glue decodes i_addr_reg[9:0] as:
//   [7:0] = physical SRAM row address
//   [8]   = weight_select  (must be 1 for weight SRAM ops)
//   [9]   = clauses_select (must be 0 for weight SRAM ops)
//
// So for weight row N: write (N | 0x100) into reg[8]
// =========================================================
task write_weight_row(input integer row, input [255:0] data);
integer w;
begin
    // Write 256-bit data as 8 x 32-bit words (LSW first)
    for (w = 0; w < 8; w = w + 1)
        apb_write_idx(w, data[32*w +: 32]);

    // Address: row address + weight select bit
    apb_write_idx(8, row | WEIGHT_SEL_BIT);

    // Command: bit[0] = weight write
    apb_write_idx(9, 32'h1);
end
endtask

task read_weight_row(input integer row, output [255:0] out);
integer w;
reg [31:0] tmp;
begin
    // Address: row address + weight select bit
    apb_write_idx(8, row | WEIGHT_SEL_BIT);

    // Command: bit[1] = weight read
    apb_write_idx(9, 32'h2);

    // Extra cycle for read data to propagate back to APB regs
    @(posedge clk_tb);
    @(posedge clk_tb);

    for (w = 0; w < 8; w = w + 1) begin
        apb_read_idx(w, tmp);
        out[32*w +: 32] = tmp;
    end
end
endtask

task load_all_weights;
integer row;
reg [255:0] rd;
begin
    $display("\n=== LOADING WEIGHTS VIA APB ===");
    for (row = 0; row < 50; row = row + 1) begin
        write_weight_row(row, weight_mem[row]);
        read_weight_row(row, rd);
        if (rd !== weight_mem[row]) begin
            $display("  Expected: %h", weight_mem[row]);
            $display("  Got     : %h", rd);
            $fatal(1, "WEIGHT MISMATCH at row %0d", row);
        end
    end
    $display("All 50 weights loaded and verified");
end
endtask

// =========================================================
// CLAUSE SRAM ACCESS
// ---------------------------------------------------------

task write_clause_row(input integer row, input [255:0] data);
integer w;
begin
    // Write 256-bit data as 8 x 32-bit words (LSW first)
    for (w = 0; w < 8; w = w + 1)
        apb_write_idx(w, data[32*w +: 32]);

    // Address: row address + clause select bit
    apb_write_idx(8, row | CLAUSE_SEL_BIT);

    // Command: bit[2] = clause write
    apb_write_idx(9, 32'h4);
end
endtask

task read_clause_row(input integer row, output [255:0] out);
integer w;
reg [31:0] tmp;
begin
    // Address: row address + clause select bit
    apb_write_idx(8, row | CLAUSE_SEL_BIT);

    // Command: bit[3] = clause read
    apb_write_idx(9, 32'h8);

    // Extra cycle for read data to propagate back to APB regs
    @(posedge clk_tb);
    @(posedge clk_tb);

    for (w = 0; w < 8; w = w + 1) begin
        apb_read_idx(w, tmp);
        out[32*w +: 32] = tmp;
    end
end
endtask

task load_all_clauses;
integer row;
reg [255:0] rd;
begin
    $display("\n=== LOADING CLAUSES VIA APB ===");
    for (row = 0; row < 140; row = row + 1) begin
        write_clause_row(row, clause_mem[row]);
        read_clause_row(row, rd);
        if (rd !== clause_mem[row]) begin
            $display("  Expected: %h", clause_mem[row]);
            $display("  Got     : %h", rd);
            $fatal(1, "CLAUSE MISMATCH at row %0d", row);
        end
    end
    $display("All 140 clauses loaded and verified");
end
endtask

// =========================================================
// IMAGE LOAD
// =========================================================
task load_image(input integer base_line_index);
integer line;
reg [127:0] line_bits;
begin
    for (line = 0; line < 8; line = line + 1) begin
        line_bits = image_mem[base_line_index + line];
        apb_write_idx(IMG_BASE_ADDR + line*4 + 0, line_bits[31:0]);
        apb_write_idx(IMG_BASE_ADDR + line*4 + 1, line_bits[63:32]);
        apb_write_idx(IMG_BASE_ADDR + line*4 + 2, line_bits[95:64]);
        apb_write_idx(IMG_BASE_ADDR + line*4 + 3, line_bits[127:96]);
    end
end
endtask

// =========================================================
// RUN INFERENCE
// =========================================================
task run_inference_and_read(output [31:0] result_out);
reg [3:0] cls;
begin
    // Trigger image transfer to class_top via image_glue_logic
    apb_write_idx(IMG_CMD_ADDR, 32'h1);

    // Wait for class_top to signal processing complete
    wait (DUT.u_class_top.img_done_wire);
    @(posedge clk_tb);   // one extra cycle for output_params to latch

    cls = DUT.u_class_top.output_params;
    result_out = {28'h0, cls};
    $display("[%0t] RESULT = %0d", $time, cls);

    // Wait for img_done_wire to deassert before the next inference
    // (img_rst in class_top resets internal state after img_done_wire)
    wait (!DUT.u_class_top.img_done_wire);
    repeat(10) @(posedge clk_tb);
end
endtask

// =========================================================
// MAIN TEST SEQUENCE
// =========================================================
reg [31:0] result1, result2;
reg [31:0] result;
integer img;

initial begin
    $dumpfile("new_tb.vcd");
    $dumpvars(0, new_tb);

    wait(rst_n_tb);
    repeat(5) @(posedge clk_tb);

    // ----- Step 1: Read data files -----
    read_image_file();
    read_weights();
    read_clauses();

    // ----- Step 2: Assert LOAD_DONE=1 (stop=1, loading mode) -----
    // class_top: stop=1 forces wea=1 and wea2=1 unconditionally
    // This ensures SRAM write ports are open during loading phase
    $display("\n[%0t] Setting LOAD_DONE=1 (stop=1, SRAM loading mode)", $time);
    apb_write_idx(LOAD_DONE_ADDR, 32'h1);
    repeat(5) @(posedge clk_tb);

    // ----- Step 3: Load weights (address encoding: row | 0x100) -----
    load_all_weights();

    // ----- Step 4: Load clauses (address encoding: row | 0x200) -----
    load_all_clauses();

    // ----- Step 5: De-assert LOAD_DONE=0 (stop=0, inference mode) -----
    // class_top: stop=0 releases wea/wea2, accelerator can now run
    $display("\n[%0t] Setting LOAD_DONE=0 (stop=0, inference mode)", $time);
    apb_write_idx(LOAD_DONE_ADDR, 32'h0);
    repeat(10) @(posedge clk_tb);

    // ----- Step 6: Write model parameters -----
    apb_write_idx(MODEL_PARAMS_ADDR, {13'b0, MODEL_PARAMS});
    $display("[%0t] Model params written: 0x%05X", $time, MODEL_PARAMS);
    repeat(5) @(posedge clk_tb);

    // ----- Step 7: Inference on 10 Images -----

for (img = 0; img < 10; img = img + 1) begin
    $display("\n[%0t] === INFERENCE ON IMAGE %0d ===", $time, img);
    load_image(img * 8);
    run_inference_and_read(result);
end
    // ----- Step 8: Final results -----
    $display("\n========================================");
    $display("FINAL RESULTS:");
    $display("  Image 1 class = %0d", result1[3:0]);
    $display("  Image 2 class = %0d", result2[3:0]);
    $display("========================================\n");

    #1000;
    $finish;
end

// =========================================================
// TIMEOUT WATCHDOG
// =========================================================
initial begin
    #150_000_000;
    $display("[%0t] SIMULATION TIMEOUT - Check for deadlock", $time);
    $finish;
end

// =========================================================
// PSLVERR MONITOR
// =========================================================
always @(posedge clk_tb) begin
    if (rst_n_tb && pslverr_tb)
        $display("[%0t] WARNING: PSLVERR asserted! addr_idx=%0d",
                 $time, paddr_tb);
end

// =========================================================
// SRAM WRITE MONITORS
// (verifies data is actually landing in SRAMs - comment out if too verbose)
// =========================================================
always @(posedge clk_tb) begin
    if (DUT.w_weight_sram_wea && DUT.w_weight_sram_ena)
        $display("[%0t] WEIGHT SRAM WRITE: addr=%0d data[31:0]=%h",
                 $time,
                 DUT.w_weight_sram_addra,
                 DUT.w_weight_sram_dina[31:0]);
end

always @(posedge clk_tb) begin
    if (DUT.w_clauses_sram_wea && DUT.w_clauses_sram_ena)
        $display("[%0t] CLAUSE SRAM WRITE: addr=%0d data[31:0]=%h",
                 $time,
                 DUT.w_clauses_sram_addra,
                 DUT.w_clauses_sram_dina[31:0]);
end

endmodule
